package java_starting;

public class division {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int n = 10;
		int i = 1;
		while (i<=n) {
			if (i%3==0) {
				System.out.print("");
			}
			else {
				System.out.println(i);
			}
			i++;
		}
	}

}
